names = [r[0] for r in MUSIC]; assert len(set(names)) == len(names)
json.dump([dict(name=n, secs=s, takes=t, prompt=p, where=w) for n, s, t, p, w in MUSIC], open(os.path.join(HERE, 'music.json'), 'w'), indent=1)
